\begin{quote}
\textbf{Abstract:}
\textit{
We prove a multidimensional version of the Szemer\'edi theorem in the primes.
Let $k$ be a positive integer and let $A$ be a set of $k$-dimensional vectors in $\mathbb{Z}^n$ with $|A| \geq n^{k-1}$.
Then there exists a set $B \subset A$ with $|B| \geq n^{k-1}/2$ such that no two vectors in $B$ are orthogonal.
}
\end{quote}

